-- Search reads directly from source records through the app's existing Supabase
-- client. These GIN trigram indexes are maintained by Postgres on every write,
-- so no service-role data mirror or historical backfill is needed.
CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA extensions;

CREATE INDEX IF NOT EXISTS universal_search_articles_title_idx ON public.articles USING gin (title extensions.gin_trgm_ops) WHERE status = 'published';
CREATE INDEX IF NOT EXISTS universal_search_articles_summary_idx ON public.articles USING gin (summary extensions.gin_trgm_ops) WHERE status = 'published';
CREATE INDEX IF NOT EXISTS universal_search_articles_body_idx ON public.articles USING gin (body_markdown extensions.gin_trgm_ops) WHERE status = 'published';

CREATE INDEX IF NOT EXISTS universal_search_notes_chapter_name_idx ON public.notes_chapters USING gin (name extensions.gin_trgm_ops) WHERE status = 'published';
CREATE INDEX IF NOT EXISTS universal_search_notes_chapter_description_idx ON public.notes_chapters USING gin (description extensions.gin_trgm_ops) WHERE status = 'published';
CREATE INDEX IF NOT EXISTS universal_search_notes_resource_title_idx ON public.notes_resources USING gin (title extensions.gin_trgm_ops) WHERE published = true;
CREATE INDEX IF NOT EXISTS universal_search_notes_resource_description_idx ON public.notes_resources USING gin (description extensions.gin_trgm_ops) WHERE published = true;
CREATE INDEX IF NOT EXISTS universal_search_notes_resource_content_idx ON public.notes_resources USING gin (content_md extensions.gin_trgm_ops) WHERE published = true;

CREATE INDEX IF NOT EXISTS universal_search_materials_title_idx ON public.materials USING gin (title extensions.gin_trgm_ops);
CREATE INDEX IF NOT EXISTS universal_search_materials_description_idx ON public.materials USING gin (description extensions.gin_trgm_ops);
CREATE INDEX IF NOT EXISTS universal_search_materials_topic_idx ON public.materials USING gin (topic extensions.gin_trgm_ops);

CREATE INDEX IF NOT EXISTS universal_search_profiles_name_idx ON public.profiles USING gin (full_name extensions.gin_trgm_ops) WHERE is_guest IS NOT TRUE;
CREATE INDEX IF NOT EXISTS universal_search_profiles_username_idx ON public.profiles USING gin (username extensions.gin_trgm_ops) WHERE is_guest IS NOT TRUE;
